# --- the cases, shared verbatim with `gold450.py` (which ran them on the baseline) ------------------------------------
# A case loads a synthetic project config -- a JSON file in a test-owned tree, or a document passed in -- and records
# the resulting config or the exact refusal. `$HOME` points into that tree. Stood in on the launcher, and recorded: the
# no-follow reader (root is `os.geteuid()` stubbed to 0), the session-directory default, the board URL default, the
# board-environment pass and the control-repository boundary check, so nothing reads a real home, account, staging
# directory or tenant file. The working directory is a test-owned one (a role with no workdir falls back to it). The slug and prefix validators, the path helpers, the JSON reader, the role and worker-pool
# parsers, the board socket default and the config type itself are the launcher's own, recorded there and passed through.
# The default config directory is rebound on the launcher into the tree. Nothing outside it is read or written.
def R(role, slot=None, workdir="own", **kw):
    """A role entry; by default with its own workdir, `wd-<role>`. workdir=None leaves it out, so the loader's default applies."""
    own = {"workdir": f"wd-{role}"} if workdir == "own" else ({} if workdir is None else {"workdir": workdir})
    return {"role": role, "cli": ["codex"], **({"slot": slot} if slot is not None else {}), **own, **kw}


def BARE(roles=("director", "main")):
    return [R(r, i, workdir=None) for i, r in enumerate(roles)]


