FUNCTIONS = ("load_project_config",)


def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s loader, in a fresh test-owned tree; every host-facing seam a stand-in on `t`."""
    import dataclasses, json, os, shutil, tempfile
    from pathlib import Path as _P
    from types import SimpleNamespace
    calls: list = []
    tmp = _P(tempfile.mkdtemp(prefix="syrd450-")).resolve()

    def norm(value):
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {"dataclass": type(value).__qualname__, **{f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in value.items()}
        if isinstance(value, _P):
            return "PATH " + str(value).replace(str(tmp), "TMP")
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        if isinstance(value, SimpleNamespace):
            return "NS"
        return repr(value).replace(str(tmp), "TMP")

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    passed = ("_validate_project_slug", "validate_ticket_prefix", "_expand_path", "_normalized_path", "_load_json", "_role_from_json",
              "parse_worker_pool", "_default_board_socket", "ProjectConfig")
    stood = ("read_tenant_document_no_follow", "default_session_dir_for_user", "_default_board_url", "_with_project_board_env",
             "_control_repository_boundary_error", "DEFAULT_CONFIG_DIR")
    saved = {n: getattr(t, n) for n in (*FUNCTIONS, *passed, *stood)}
    saved_env = {k: os.environ.get(k) for k in ("HOME", "SYRD450_DIR")}
    saved_euid = os.geteuid
    saved_cwd = os.getcwd()
    try:
        (tmp / "cwd").mkdir()
        os.chdir(tmp / "cwd")  # a role with no workdir and no repository falls back to the working directory
        os.environ["HOME"] = str(tmp / "home")
        for k, v in spec.get("env", {}).items():
            os.environ[k] = v.replace("@", str(tmp))
        load = getattr(holder, "load_project_config")
        # "@/" at the start of a value is the test-owned tree, so a case can give an absolute path inside it.
        doc = json.loads(json.dumps(spec["doc"]).replace('"@/', '"' + str(tmp) + "/")) if "doc" in spec else None

        def passthrough(name):
            def f(*args, **kwargs):
                note(name, *args, **kwargs)
                return saved[name](*args, **kwargs)
            return f

        for n in passed:
            setattr(t, n, passthrough(n))
        t.DEFAULT_CONFIG_DIR = tmp / "default-configs"
        t.read_tenant_document_no_follow = lambda path, *, what: note("read_tenant_document_no_follow", path, what=what) or (
            (None, spec["no_follow"]) if "no_follow" in spec else (dict(doc), None))
        t.default_session_dir_for_user = lambda user: note("default_session_dir_for_user", user) or tmp / "sessions" / (user or "nobody")
        t._default_board_url = lambda project: note("_default_board_url", project) or f"http://127.0.0.1:syrd450-{project}"
        t._with_project_board_env = lambda config, roles: note("_with_project_board_env", [r.role for r in roles]) or list(roles)
        t._control_repository_boundary_error = lambda config, *, require_existing_user: note(
            "_control_repository_boundary_error", config.project, require_existing_user=require_existing_user) or spec.get("boundary")
        if spec.get("root"):
            os.geteuid = lambda: 0
        else:
            os.geteuid = lambda: 4500
        path = (tmp / "default-configs" / "p450.json") if spec.get("default_path") else (tmp / "configs" / "p450.json")
        path.parent.mkdir(parents=True, exist_ok=True)
        if "doc" in spec and not spec.get("pass_document"):
            path.write_text(json.dumps(doc), encoding="utf-8")
        elif "raw" in spec:
            path.write_text(spec["raw"], encoding="utf-8")
        kw = {"document": dict(doc)} if spec.get("pass_document") else {}
        try:
            got = load(spec.get("request", "p450"), None if spec.get("default_path") else path, **kw)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            return {"result": {"raised": type(exc).__name__, "message": norm(str(exc))}, "calls": calls}
        return {"result": norm(got), "type": type(got).__qualname__, "calls": calls}
    finally:
        os.chdir(saved_cwd)
        os.geteuid = saved_euid
        for k, v in saved_env.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        for n, v in saved.items():
            setattr(t, n, v)
        shutil.rmtree(tmp)
