def test_either_import_order_gives_one_set_of_objects_and_no_defaults() -> None:
    for order in (("scripts.project_config_loader", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.project_config_loader")):
        result = python("import importlib, inspect; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.project_config_loader as m; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        "[(k, v.kind.name, v.default) for k, v in inspect.signature(m.load_project_config).parameters.items()], "
                        f"not any(hasattr(m, n) for n in ('launcher', 'team_launcher', 'ProjectConfig', 'RoleConfig', *{sorted(SEAMS['load_project_config'])!r})))")
        check(result.stdout.strip() == "True [('project', 'POSITIONAL_OR_KEYWORD', <class 'inspect._empty'>), "
                                       "('config_path', 'POSITIONAL_OR_KEYWORD', None), ('document', 'KEYWORD_ONLY', None)] True",
              f"{' then '.join(order)}: one object; the same parameters and defaults; nothing of the launcher or its imports bound at load: {result.stdout}{result.stderr[-600:]}")
    import dataclasses
    import typing
    check(m.os is os and m.replace is dataclasses.replace and m.Path is Path and m.Any is typing.Any and m.Mapping is typing.Mapping
          and m.TYPE_CHECKING is False and t.os is m.os and t.replace is m.replace and t.Path is m.Path,
          "the standard-library names are the module's own, the very objects the launcher holds")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "project_config_loader.py").read_text(encoding="utf-8"))
    for name in FUNCTIONS:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS.get(name, {})
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        first = 1 if ast.get_docstring(node) is not None else 0
        check(imports == ["from scripts import team_launcher as launcher"] and ast.unparse(node.body[first]) == imports[0],
              f"{name}: the launcher imported first thing, and nothing else imported: {imports}")
        skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs), *[d for d in node.args.kw_defaults if d]]
                if part is not None for y in ast.walk(part)}
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
        check(bare == [], f"{name}: none of them read past it: {bare}")
        # The two security-sensitive checks, where the baseline has them. Root, reading a file the tenant owns, reads it
        # only through the no-follow reader, before any other read of it; and the control-repository boundary is checked
        # on the parsed config before anything is returned.
        calls = [(x.lineno, ast.unparse(x.func)) for x in ast.walk(node) if isinstance(x, ast.Call)]
        at = lambda func: sorted(line for line, f in calls if f == func)
        root = [ast.unparse(x.test) for x in ast.walk(node) if isinstance(x, ast.If) and "os.geteuid()" in ast.unparse(x.test)]
        returns = [x.lineno for x in ast.walk(node) if isinstance(x, ast.Return)]
        check(root == ["document is None and os.geteuid() == 0"] and at("os.geteuid") == [next(x.test.lineno for x in ast.walk(node) if isinstance(x, ast.If) and "os.geteuid()" in ast.unparse(x.test))]
              and len(at("launcher.read_tenant_document_no_follow")) == 1 and len(at("launcher._load_json")) == 1
              and at("launcher.read_tenant_document_no_follow")[0] < at("launcher._load_json")[0],
              f"{name}: root, with no document passed, reads the tenant's file only through the no-follow reader, the os module's geteuid deciding: {root}")
        check(len(at("launcher._control_repository_boundary_error")) == 1 and len(returns) == 1
              and at("launcher._control_repository_boundary_error")[0] < returns[0] and at("launcher.ProjectConfig")[0] < at("launcher._control_repository_boundary_error")[0],
              f"{name}: the control-repository boundary is checked on the parsed config, before the one return: {returns}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import os", "from dataclasses import replace", "from pathlib import Path",
                  "from typing import TYPE_CHECKING, Any, Mapping"]
          and tc == ["if TYPE_CHECKING:\n    from scripts.team_launcher import ProjectConfig, RoleConfig"],
          f"the standard library, and the two config types for annotations only: {top} {tc}")
    names = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign, ast.AnnAssign))]
    check(names == list(MOVED), f"the one function, and nothing else: {names}")


def test_the_launcher_reexports_it_and_its_readers_reach_it_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.project_config_loader"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the loader, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))),
          "at the top, above every definition and constant that could read it")
    # Annotated constants count too.
    defined = ({getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
               | {n.target.id for n in tree.body if isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name)})
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    seams = {name for reads in SEAMS.values() for name in reads} - set(MOVED)
    check(not defined & set(MOVED) and seams | {"RoleConfig", *DISPATCH} <= defined | exported,
          "the launcher defines none of it, and keeps its callers and every seam it reads, its own or re-exported")
    uses: dict = {}
    for fn in launcher_body(ROOT, tree):
        if isinstance(fn, (ast.FunctionDef, ast.ClassDef)):
            for x in ast.walk(fn):
                if isinstance(x, ast.Name) and x.id in MOVED:
                    uses.setdefault(fn.name, {}).setdefault(x.id, 0)
                    uses[fn.name][x.id] += 1
    check(uses == DISPATCH, f"the launcher's own callers name it exactly as often as before, by its re-exported name: {uses}")
    past = sorted(ast.unparse(x) for x in ast.walk(tree) if isinstance(x, ast.Attribute) and x.attr in MOVED)
    loose = sorted({x.id for n in tree.body if not isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Import, ast.ImportFrom)) for x in ast.walk(n)
                    if isinstance(x, ast.Name) and x.id in MOVED})
    check(past == [] and loose == [], f"and nothing reaches past the launcher's name, or reads it at module level: {past} {loose}")
    for path, counts in READERS.items():
        source = ast.parse((ROOT / path).read_text(encoding="utf-8"))
        got: dict[str, int] = {}
        for x in ast.walk(source):
            if isinstance(x, ast.Attribute) and x.attr in MOVED and isinstance(x.value, ast.Name) and x.value.id in ("launcher", "team_launcher"):
                got[ast.unparse(x)] = got.get(ast.unparse(x), 0) + 1
        bare = sorted({x.id for x in ast.walk(source) if isinstance(x, ast.Name) and x.id in MOVED})
        check(dict(sorted(got.items())) == counts and bare == [], f"{path} still reads it through the launcher, as often as before: {got} {bare}")


