def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def steps(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    def refusal(label):
        return result(label).get("message") if result(label).get("raised") == "SystemExit" else None

    C = "TMP/configs/p450.json"
    # The no-follow root read (SYRD-228).
    check([c for c in GOLDEN["root: the no-follow reader answers"]["calls"] if c[0] == "read_tenant_document_no_follow"]
          == [["read_tenant_document_no_follow", ["PATH " + C], {"what": "p450's generated configuration"}]]
          and "_load_json" not in steps("root: the no-follow reader answers")
          and result("root: the no-follow reader answers") == result("a minimal config"),
          "root reads the tenant's file only through the no-follow reader, naming it, and never follows it with a plain read")
    check(refusal("root: the no-follow reader refuses") == "switchyard: refusing to read p450's generated configuration at X: it is a symlink. Nothing was changed."
          and steps("root: the no-follow reader refuses") == ["_validate_project_slug", "read_tenant_document_no_follow"],
          "a no-follow refusal stops root at once, saying nothing was changed")
    check("read_tenant_document_no_follow" not in steps("a minimal config") and "_load_json" in steps("a minimal config")
          and not {"read_tenant_document_no_follow", "_load_json"} & set(steps("root with a document passed in") + steps("a document passed in")),
          "a caller that is not root reads its own file as before; a document passed in is never read again, by root either")
    # Report tokens.
    check(refusal("an inline upstream report token") == f"{C} stores an upstream report token value in upstream_report_token; use upstream_report_token_file instead"
          and refusal("both inline tokens") == f"{C} stores an upstream report token value in upstream_report_token, tenant_report_token; use upstream_report_token_file instead"
          and "raised" not in result("a blank inline token")
          and (result("the legacy report keys")["upstream_report_url"], result("the legacy report keys")["upstream_report_token_file"]) == ("http://legacy", "legacy-tok"),
          "a token value in the config is refused, naming every key holding one; a blank one is not; the legacy keys are read")
    # The repository relationships and the boundary.
    check(refusal("a worktree base without a repository") == f"{C} must not define worktree_base without repository"
          and refusal("a control repository without a repository") == f"{C} must not define control_repository without repository"
          and refusal("a control repository without a worktree base") == f"{C} must define worktree_base when control_repository is set",
          "a worktree base or a control repository needs the repository, and a control repository its worktree base")
    check([c[2]["default_workdir"] for c in GOLDEN["a control repository with its worktrees"]["calls"] if c[0] == "_role_from_json"]
          == ["PATH TMP/configs/wt/director", "PATH TMP/configs/wt/main"]
          and [c[2]["default_workdir"] for c in GOLDEN["a control repository, one role with its own workdir"]["calls"] if c[0] == "_role_from_json"]
          == ["PATH TMP/configs/repo", "PATH TMP/configs/wt/main"]
          and [c[2]["default_workdir"] for c in GOLDEN["two roles sharing the repository"]["calls"] if c[0] == "_role_from_json"]
          == ["PATH TMP/configs/repo", "PATH TMP/configs/repo"]
          and refusal("a control repository, a role with a blank name") == "team launcher role entry missing role",
          "with a control repository a role with no workdir defaults to its own worktree under the base; otherwise to the repository")
    check([c for c in GOLDEN["a control repository with its worktrees"]["calls"] if c[0] == "_control_repository_boundary_error"]
          == [["_control_repository_boundary_error", ["p450"], {"require_existing_user": False}]]
          and refusal("the control repository refused at the boundary") == f"{C} control_repository is outside the managed root"
          and steps("the control repository refused at the boundary")[-2:] == ["ProjectConfig", "_control_repository_boundary_error"]
          and steps("a minimal config")[-2:] == ["_control_repository_boundary_error", "_with_project_board_env"],
          "the boundary is checked on the parsed config, not requiring the user to exist yet; a refusal returns nothing, before any board env")
    # The project, and the roles.
    check(refusal("a project that does not match") == "config project 'other' does not match requested project 'p450'"
          and refusal("an invalid slug").startswith("switchyard: project slug must match")
          and result("a slug in capitals")["project"] == result("the project from the request")["project"] == "p450",
          "the requested project and the config's must be the same valid slug")
    check(refusal("no roles") == refusal("roles that are not a list") == refusal("an empty roles list") == f"{C} must define a non-empty roles list"
          and refusal("a role that is not an object") == f"{C} roles must all be JSON objects"
          and refusal("duplicate slots") == f"{C} contains duplicate role slot assignments"
          and refusal("a detached role with a slot") == f"{C} detached roles must not define layout slots: main"
          and refusal("a visible role without a slot") == f"{C} visible roles must define layout slots: main"
          and "raised" not in result("a detached role without a slot"),
          "roles: a non-empty list of objects; slots unique, only on visible roles, and on every one of them")
    check(refusal("two roles sharing a workdir") == f"{C} contains duplicate non-shared role workdir assignments: director/main:TMP/configs/shared"
          and refusal("roles with no workdir and no repository share the working directory") == f"{C} contains duplicate non-shared role workdir assignments: director/main:TMP/cwd"
          and "raised" not in result("two roles sharing the repository") and "raised" not in result("a role workdir that is the repository, given twice"),
          "two roles may share only the repository")
    # Defaults, and what the config may give instead.
    r = result("a minimal config")
    check(GOLDEN["a minimal config"]["type"] == "ProjectConfig"
          and (r["project_name"], r["ticket_prefix"], r["board_url"], r["board_socket"], r["worktree_remote"], r["worktree_branch"], r["role_state_isolation"])
          == ("p450", "P450", "http://127.0.0.1:syrd450-p450", "/run/p450-ticket-board/ticket-board.sock", "origin", "main", False)
          # The default layout file (its exact name is in GOLDEN) sits beside the config and is named for the project.
          and r["layout"].rsplit("/", 1)[0] == "PATH TMP/configs" and r["layout"].rsplit("/", 1)[1].startswith("p450-")
          and r["layout"].endswith("-layout.json")
          and r["session_dir"] == "PATH TMP/sessions/nobody" and result("an owner without a session directory")["session_dir"] == "PATH TMP/sessions/p450-agent"
          and result("a name, not a project name")["project_name"] == "Named 450",
          "the defaults: the project as name and prefix, the layout beside the config, the owner's session directory, the board's own URL and socket, origin/main")
    e = result("every field")
    check((e["board_url"], e["board_socket"], e["upstream_report_url"], e["upstream_report_token_file"], e["run_as_user"], e["pane_launcher"], e["session_dir"], e["role_state_isolation"])
          == ("http://b:1", "/run/x.sock", "http://up", "tok", "p450-agent", "PATH TMP/configs/bin/pl", "PATH TMP/configs/sess", True)
          and "default_session_dir_for_user" not in steps("every field")
          and (result("a remote and branch given")["worktree_remote"], result("a remote and branch given")["worktree_branch"]) == ("up", "dev")
          and refusal("an empty worktree remote") == refusal("an empty worktree branch") == f"{C} worktree_remote and worktree_branch must be non-empty",
          "given values are stripped and win; relative paths resolve beside the config; a blank remote or branch is refused")
    check(result("a home-relative repository")["repository"] == "PATH TMP/home/repo"
          and result("an absolute layout and session directory")["layout"] == "PATH TMP/abs/lay.json"
          and result("an environment-variable layout")["layout"] == "PATH TMP/envdir/lay.json"
          and result("the default config path")["layout"] == r["layout"].replace("TMP/configs/", "TMP/default-configs/"),
          "paths expand ~ and variables, keep absolute ones, and a config found by default sits in the default config directory")
    check(result("a worker pool")["worker_pool"]["dataclass"] == "WorkerPool" and result("a worker pool")["worker_pool"]["size"] == 2
          and refusal("a worker pool refused") == f"{C} worker_pool name must be lowercase letters, digits and dashes: 'Bad Pool'",
          "the worker pool is parsed, and refused, against the config's path")
    check(result("a config that is not JSON")["raised"] == "JSONDecodeError" and result("a missing config")["raised"] == "FileNotFoundError"
          and refusal("a config that is not an object") == f"{C} must contain a JSON object",
          "a non-root caller's unreadable file raises as it always did (the baseline's behaviour, kept)")


def test_every_launcher_seam_is_reached() -> None:
    # Every function the loader reads on the launcher is a recorder or stand-in there; the one constant, the default
    # config directory, is rebound there and changes the answer ("the default config path").
    names = {name for reads in SEAMS.values() for name in reads}
    constants = {name for name in names if not callable(getattr(t, name))}
    check(constants == {"DEFAULT_CONFIG_DIR"} and names - constants <= REACHED,
          f"a recorder on the launcher reached every function: missing {sorted(names - constants - REACHED)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_set_of_objects_and_no_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_it_and_its_readers_reach_it_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"project_config_loader_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
